style.css:
@-moz-document domain("twitch.tv") {
/* === Общий фон === */
  html, body, #root, .layout-root, .tw-root {
    background-color: #e6ffcc !important; /* светло-салатовый */
    background-image: none !important;
    transition: background-color 0.6s ease, color 0.4s ease !important;
  }

  /* Убираем тёмные и полупрозрачные фоны */
  .tw-overlay, 
  .tw-c-background-base,
  .tw-c-background-alt,
  .tw-c-background-body,
  .tw-transition,
  [class*="background"],
  [class*="theme-dark"],
  [class*="ScCoreButton"] {
    background: transparent !important;
    background-image: none !important;
    transition: background-color 0.6s ease, color 0.4s ease !important;
  }

  /* === Текст === */
  body, 
  .tw-ellipsis, 
  .tw-c-text, 
  span, 
  p, 
  h1, h2, h3, h4, h5, h6,
  a, 
  div, 
  button {
    color: #000000 !important;
    text-shadow: none !important;
    transition: color 0.4s ease !important;
  }

  /* === При наведении курсора текст не меняет цвет === */
  a:hover,
  button:hover,
  .tw-link:hover,
  .tw-interactive:hover {
    color: #000000 !important;
  }

  /* === Убираем спецэффекты и яркие рамки === */
  * {
    box-shadow: none !important;
    border-color: rgba(0, 0, 0, 0.2) !important;
    transition: all 0.4s ease !important;
  }

  /* === Видео-плеер не трогаем === */
  video {
    background: #000 !important;
  }
}
